// ladder.mjs — the universal landmark ladder (A_j, tau_j, H_j) generated by the round table:
//   A_0 = 7, tau_0 = 9; H_j = nu2(A_j+1); (A_{j+1}, tau_{j+1}) = (A_j + dAlpha(H_j), tau_j + dt(H_j)).
// The ladder is the m/w/alpha-class-independent skeleton of EVERY Phi-trajectory (the walk is
// autonomous). Also: margin checks (tau_j >= 2*H_j + 16 for j >= j0; the early exceptions are
// covered by concrete-t derivations (3,9),(1,13),(2,18)); and the induction-start locator
//   j0(h) = last j with tau_j <= h-1-MARGIN  (master derivation covers the rest).
// Usage: node ladder.mjs [MARGIN=64] [JMAX=200000]
import { readFileSync, writeFileSync } from 'fs';

const MARGIN = BigInt(+(process.argv[2] ?? 64));
const JMAX = +(process.argv[3] ?? 200000);
const DA = [], DT = [];
for (const l of readFileSync('sym4-table.txt', 'utf8').split('\n')) {
  const m = l.match(/h=(\d+).*da=(\d+) dt=(\d+)/);
  if (m) { DA[+m[1]] = BigInt(m[2]); DT[+m[1]] = +m[3]; }
}
const v2 = (x) => { let c = 0n; x = BigInt(x); while (x % 2n === 0n) { c++; x /= 2n; } return Number(c); };
const lad = [];
let A = 7n, T = 9n;
const TMAXV = DA.length - 1;
for (let j = 0; j < JMAX; j++) {
  const H = v2(A + 1n);
  if (DA[H] === undefined) { console.log(`ladder stops at j=${j}: class H=${H} exceeds table (${TMAXV})`); break; }
  lad.push({ A, tau: T, H });
  A += DA[H]; T += BigInt(DT[H]);
  if (T > 2n ** 64n) break; // far beyond any need
}
console.log(`ladder generated: ${lad.length} positions, last = (A=${A}, tau=${T})`);
// margin check: tau_j >= 2*H_j + 16 for j >= 3 (exceptions j=0,1,2 -> concrete-t bases)
let margBad = 0;
for (let j = 3; j < lad.length; j++) {
  if (lad[j].tau < BigInt(2 * lad[j].H + 16)) { if (margBad < 5) console.log(`MARGIN VIOLATION j=${j}: tau=${lad[j].tau} H=${lad[j].H}`); margBad++; }
}
console.log(`margin tau_j >= 2H_j+16 for j>=3: ${lad.length - 3 - margBad}/${lad.length - 3} ok, ${margBad} violations`);
// first-fitting position for a given h: last j with tau_j + dt(H_j) <= h-1 (informational)
// induction-start locator j0(h) = last j with tau_j <= h-1-MARGIN
function j0of(h) {
  let j = 0; while (j + 1 < lad.length && lad[j + 1].tau <= BigInt(h) - 1n - MARGIN) j++; return j;
}
// dump the ladder + locators for h in the verification range
const rows = [];
for (let j = 0; j < Math.min(lad.length, 40); j++) rows.push(`j=${j}: A=${lad[j].A} tau=${lad[j].tau} H=${lad[j].H}`);
console.log(rows.join(' | '));
writeFileSync('ladder.json', JSON.stringify({ margin: Number(MARGIN), ladder: lad.map(x => ({ A: String(x.A), tau: String(x.tau), H: x.H })) }));
// sanity: the band structure of the table vs ladder j0
const tab = new Map();
for (const l of readFileSync('sym4-table.txt', 'utf8').split('\n')) {
  const m = l.match(/h=(\d+).*da=(\d+) dt=(\d+)/); if (m) tab.set(+m[1], [BigInt(m[2]), +m[3]]);
}
console.log('ladder.json written (' + lad.length + ' positions)');
